schema_ddl:
CREATE TABLE agenzie (
    ag_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_agenzia TEXT NOT NULL,
    citta TEXT NOT NULL,
    CONSTRAINT chk_nome_agenzia CHECK (length(nome_agenzia) > 0)
);

CREATE TABLE immobili (
    codice_immobile TEXT PRIMARY KEY,
    ag_id INT NOT NULL REFERENCES agenzie(ag_id),
    indirizzo TEXT NOT NULL,
    prezzo NUMERIC(12,2) NOT NULL CHECK (prezzo > 0),
    superficie INT NOT NULL CHECK (superficie > 0)
);

CREATE TABLE contratti (
    contratto_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_immobile TEXT NOT NULL REFERENCES immobili(codice_immobile),
    tipo_contratto TEXT NOT NULL CHECK (tipo_contratto IN ('vendita', 'affitto')),
    data_stipula DATE NOT NULL,
    valore_transazione NUMERIC(12,2) NOT NULL CHECK (valore_transazione >= 0)
);
